"""Offline resource inventory, not a plugin manifest or installation format."""
import csv,json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def load(p):return json.loads(p.read_text())
def write(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 rows=load(R/'build/resource-index.json')['items'];profiles=load(R/'data/physical-profiles.json')['profiles'];sources=load(R/'data/sources.json')['items'];pmap={p['id']:p for p in profiles};smap={s['id']:s for s in sources}
 for x in rows:
  p=pmap[x['physical_profile']];x['physical']=p;x['source']=smap[p['source_id']];x['files']=[{'name':'Portable GLB','path':x['path']+'/material.glb'},{'name':'Editable glTF','path':x['path']+'/material.gltf'},{'name':'Physical reference','path':x['path']+'/physical-profile.json'},{'name':'Appearance','path':x['path']+'/appearance.json'},{'name':'Proposed native commands','path':x['path']+'/native-material-commands.json'}]
 write(R/'resource-index.json',{'plugin_standard':None,'count':len(rows),'profiles':len(profiles),'all_source_properties_complete':False,'items':rows})
 with (R/'resource-index.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['id','name','family','physical_profile','preview','source','condition','native_validation','premium_qualification'])
  for x in rows:w.writerow([x['id'],x['name'],x['family'],x['physical_profile'],x['preview'],x['source']['url'],x['physical']['condition'],'not_run','pending'])
 write(R/'global-inventory.json',{'kind':'internal_federated_inventory_not_plugin_standard','expected_total':2002,'collections':[{'id':'catalog-v1','records':1386,'source':'catalog/Catalog.json','release':'catalog-v1-20261024'},{'id':'woods-stage01','records':400,'source':'authoring/stage-01-woods/registry/global-index.json','release':'wood-stage01-20261025'},{'id':'alloys-stage02','records':216,'source':'authoring/stage-02-alloys/resource-index.json','physical_profiles':24,'appearance_variants':192}], 'legacy_coverage_unchanged':{'candidate_physical_links':345,'no_specific_physical_reference':303},'plugin_standard':None})
 page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Alloy authoring collection</title><style>body{margin:0;background:#111820;color:#e6edf3;font:16px system-ui}header,main{padding:30px 4vw}header{background:#1b2632}h1{font-size:38px;margin:8px 0}p{line-height:1.55;max-width:1000px}input,select,button{font:inherit;padding:12px;background:#243241;color:inherit;border:1px solid #647587;border-radius:8px}a{color:#a7daff}#grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:18px;margin-top:20px}.card{background:#1e2935;border:1px solid #41566b;border-radius:12px;padding:14px}.card img{width:100%;border-radius:8px}.card h3{font-size:17px}.meta{color:#a9bed2;font-size:14px}dialog{max-width:950px;width:85vw;background:#1b2632;color:inherit;border:1px solid #60768a;border-radius:12px}dialog::backdrop{background:#000a}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:9px;border-bottom:1px solid #506070}code{overflow-wrap:anywhere}</style><header><small>SOLIDCRAFT · PERSONAL AUTHORING COLLECTION</small><h1>Metal alloys · Stage 02</h1><p><strong>24 grade/condition references · 23 distinct alloy grades · 192 surface variants</strong><br>Each appearance links to a physical reference with source, units and condition. Images are original software studies, not native SolidCraft acceptance. No plugin or installation standard is defined.</p><p><a href="README.md">Scope & limitations</a> · <a href="data/property-index.csv">Physical properties CSV</a> · <a href="resource-index.json">Resource index</a> · <a href="global-inventory.json">Global inventory</a> · <a href="reports/source-review.json">Source discrepancies</a></p></header><main><input id="q" placeholder="Search grade, finish, family" size="40"><select id="family"><option value="">All families</option></select> <span id="count"></span><div id="grid"></div></main><dialog id="detail"><button id="close">Close</button><div id="body"></div></dialog><script>const items=DATA;const esc=x=>String(x??'unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const q=document.querySelector('#q'),f=document.querySelector('#family'),grid=document.querySelector('#grid');for(const fam of [...new Set(items.map(x=>x.family))].sort()){const o=document.createElement('option');o.value=o.textContent=fam;f.append(o)}function draw(){const a=items.filter(x=>(!f.value||x.family===f.value)&&JSON.stringify([x.id,x.name,x.family]).toLowerCase().includes(q.value.toLowerCase()));document.querySelector('#count').textContent=a.length+' variants';grid.innerHTML=a.map(x=>`<article class="card"><img loading="lazy" src="${esc(x.preview)}" alt="Procedural appearance study"><h3>${esc(x.name)}</h3><p class="meta">${esc(x.physical.condition)}</p><button data-id="${esc(x.id)}">Appearance & physical data</button></article>`).join('')}q.oninput=draw;f.onchange=draw;grid.onclick=e=>{const id=e.target.dataset.id;if(!id)return;const x=items.find(v=>v.id===id);document.querySelector('#body').innerHTML=`<h2>${esc(x.name)}</h2><img src="${esc(x.preview)}" width="480"><p>${esc(x.physical.condition)}</p><p>${x.files.map(v=>`<a href="${esc(v.path)}">${esc(v.name)}</a>`).join(' · ')}</p><p>Source: <a href="${esc(x.source.url)}">${esc(x.source.title)}</a>. Retrieved ${esc(x.source.retrieved)}.</p><table><tr><th>Quantity</th><th>SI value</th><th>Conditions</th></tr>${x.physical.properties.map(v=>`<tr><td>${esc(v.quantity)}</td><td>${esc(JSON.stringify(v.value))} ${esc(v.unit)}</td><td>${esc(v.temperature_k===null?(v.temperature_interval_k?JSON.stringify(v.temperature_interval_k)+' K interval':'Temperature not stated'):v.temperature_k+' K')}<br>${esc(v.qualifier)}</td></tr>`).join('')}</table><p>Not design allowables. Missing properties remain unknown: ${esc(x.physical.missing_properties.join(', '))}. No automatic engineering assignment.</p>`;document.querySelector('#detail').showModal()};document.querySelector('#close').onclick=()=>document.querySelector('#detail').close();draw();</script>'''
 page=page.replace('DATA',json.dumps(rows).replace('</','<\\/'));(R/'index.html').write_text(page)
 print('GALLERY',len(rows),'linked appearances; global federation 2002 records')
if __name__=='__main__':main()
